HALT = False


def read(path, default=None):
    p = Path(path)
    if p.is_symlink():
        raise RuntimeError('拒绝读取链接：' + str(p))
    return json.loads(p.read_text(encoding='utf-8-sig')) if p.is_file() else default


def plain(value):
    if isinstance(value, dict): return {str(k): plain(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)): return [plain(v) for v in value]
    if hasattr(value, 'detach'): return plain(value.detach().cpu().numpy())
    if hasattr(value, 'tolist'): return plain(value.tolist())
    if isinstance(value, float) and not math.isfinite(value): return None
    return value


def save(path, value):
    p = Path(path); p.parent.mkdir(parents=True, exist_ok=True)
    if p.is_symlink(): raise RuntimeError('拒绝覆盖链接：' + str(p))
    tmp = p.with_name(p.name + '.pending_' + str(os.getpid()))
    tmp.write_text(json.dumps(plain(value), ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    os.replace(tmp, p)


def sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''): h.update(block)
    return h.hexdigest()


def source_module(name, raw, filename):
    tree = ast.parse(raw.decode('utf-8-sig'))
    tree.body = [n for n in tree.body if not (isinstance(n, ast.If) and '__name__' in ast.unparse(n.test))]
    module = types.ModuleType(name); module.__file__ = str(filename); sys.modules[name] = module
    exec(compile(tree, str(filename), 'exec'), module.__dict__)
    return module


def base_module():
    raw = zlib.decompress(base64.b85decode(BASE_B85))
    if hashlib.sha256(raw).hexdigest() != BASE_SHA: raise RuntimeError('封存环境入口校验失败')
    module = source_module('uam_frozen_transfer', raw, __file__)
    import cloudpickle
    cloudpickle.register_pickle_by_value(module)
    original=module.gym_class
    def instrumented(m):
        Parent=original(m)
        class Phase(Parent):
            def step(self,action):
                phase=self.phase
                if phase==0:
                    self._active_p=bool(self.env.scenario.waiting_decisions)
                    self._focal_id=str(self.env.scenario.waiting_decisions[0]) if self._active_p else None
                result=super().step(action)
                if phase==1 and self.ledger['decision_log']:
                    self.ledger['decision_log'][-1].update(passenger_active=self._active_p,focal_id=self._focal_id)
                return result
        return Phase
    module.gym_class=instrumented
    return module


def task(arm, seed, steps, phase='CORE'):
    return dict(id=f'{phase}__E1__K3__{arm}__s{seed}', arm=arm, seed=seed, steps=int(steps),
                environment='E1', k=3, fleet=12, control='J3', method='J3__M0_BASE',
                variant='M0_BASE', reward_mode='PT_POST', time_mode='RAW', timing=True,
                batch=True, network='TRANSFORMER', gamma=.99, space=True, temporal=False, phase=phase)


def tasks_make():
    """固定各组及种子，按完整配对块安排先后；不按中途成绩更换方法。"""
    result = []
    if SUITE == 'core':
        arms = ('HAPPO_RANDOM', 'MAPPO_MATCHED', 'HAPPO_FIXED_PF', 'HAPPO_FIXED_AF', 'HAPPO_SHARED', 'PPO_TF')
        for seed in range(2101, 2109):
            order = list(arms); random.Random(seed).shuffle(order)
            result.extend(task(arm, seed, 1_996_800) for arm in order)
        # 给两篇新世界模型配套同种子、同长度的普通RL参照；不能拿2M胜负冒充1M公平比较。
        for seed in range(2301, 2309):
            order=['HAPPO_RANDOM','MAPPO_MATCHED','PPO_TF']; random.Random(seed).shuffle(order)
            result.extend(task(arm,seed,1_003_520,'WM_MATCHED') for arm in order)
        for seed in range(2201, 2205):
            arms = ['DV3_FULL', 'DV3_SHORT', 'DV3_NO_RECON_REP', 'DV3_NO_TASK_REP']
            random.Random(seed).shuffle(arms)
            result.extend(task(arm, seed, 1_003_520, 'DREAMER') for arm in arms)
    else:
        main_arms=('FULL','NO_AGG') if SUITE=='marie' else ('FULL','JOINT')
        supplementary=('LOCAL_CONTEXT','SHORT_HORIZON') if SUITE=='marie' else ('REVERSE_ORDER','LONG_HORIZON')
        for seed in range(2301,2309):
            order=list(main_arms)+(list(supplementary) if seed<2305 else [])
            random.Random(seed).shuffle(order)
            result.extend(task(SUITE.upper()+'_'+arm,seed,1_003_520,'CORE') for arm in order)
    for i, item in enumerate(result, 1): item['run_order'] = i
    return result


