def atomic_pickle(path, value):
    p = Path(path); tmp = p.with_name(p.name + '.pending')
    with tmp.open('wb') as stream: pickle.dump(value, stream, protocol=5)
    os.replace(tmp, p)


def stopping(root): return HALT or (Path(root) / 'STOP_REQUESTED').exists()


def stop_signal(number, frame):
    global HALT
    HALT = True


def lock_file(path):
    p = Path(path); p.parent.mkdir(parents=True, exist_ok=True); handle = p.open('a+b')
    if os.name == 'nt':
        import msvcrt
        if p.stat().st_size == 0: handle.write(b'0'); handle.flush()
        handle.seek(0); msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
    else:
        import fcntl
        fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
    return handle


def alive(pid):
    if not isinstance(pid, int) or pid <= 0: return False
    try: os.kill(pid, 0); return True
    except ProcessLookupError: return False
    except PermissionError: return True


class GpuLease:
    """三文件共享准入账本；只协调自己的工作进程，不抢占或终止其他用户。"""
    def __init__(self, root, reserve):
        self.root, self.reserve = Path(root), float(reserve)
        self.directory = PROJECT / 'workspace/artifacts/uam_190m_gpu_admission'
        self.directory.mkdir(parents=True, exist_ok=True)
        self.path = self.directory / (str(os.getpid()) + '.json')
    def __enter__(self):
        if not os.environ.get('CUDA_VISIBLE_DEVICES'): raise RuntimeError('请显式指定CUDA_VISIBLE_DEVICES')
        while True:
            if stopping(self.root): raise InterruptedError('等待资源时收到停止请求')
            try: guard = lock_file(self.directory / 'admission.lock')
            except (OSError, BlockingIOError): time.sleep(2); continue
            try:
                visible = os.environ['CUDA_VISIBLE_DEVICES'].split(',')[0]
                query = subprocess.run(['nvidia-smi', '-i', visible, '--query-gpu=memory.free,memory.total', '--format=csv,noheader,nounits'], capture_output=True, text=True)
                if query.returncode: raise RuntimeError('无法读取指定GPU，不静默转CPU')
                free, total = [float(x.strip()) / 1024 for x in query.stdout.strip().split(',')]
                proc = subprocess.run(['nvidia-smi', '-i', visible, '--query-compute-apps=pid,used_memory', '--format=csv,noheader,nounits'], capture_output=True, text=True)
                allocated = {}
                for line in proc.stdout.splitlines():
                    try: pid, memory = line.split(','); allocated[int(pid)] = float(memory) / 1024
                    except ValueError: continue
                gap = 0.
                for p in self.directory.glob('*.json'):
                    record = read(p, {})
                    if record.get('device') == visible and alive(record.get('pid', -999999)):
                        gap += max(0., record['reserve_gib'] - allocated.get(record['pid'], 0.))
                if self.reserve > total - 1: raise RuntimeError('预留显存超过本卡容量；保持原模型，不自动缩小')
                if free >= self.reserve + gap + .5:
                    save(self.path, dict(pid=os.getpid(), device=visible, reserve_gib=self.reserve, root=str(self.root), time=time.time()))
                    return self
                save(self.root / 'RESOURCE_WAIT.json', dict(pid=os.getpid(), free_gib=free, reserved_gap_gib=gap, need_gib=self.reserve, time=time.time(), status='等待显存，不改变算法'))
            finally: guard.close()
            time.sleep(30)
    def __exit__(self, *unused):
        if self.path.is_file(): self.path.unlink()


def materialize_author(name, root, vendor_dir):
    """核对锁定作者文件后，只复制到本轮自己的沙盒，不原地改作者目录。"""
    source = Path(vendor_dir).resolve(); expected = SOURCE_HASHES[name]
    for relative, wanted in expected.items():
        p = source / relative
        if not p.is_file() or p.is_symlink() or sha(p) != wanted:
            raise RuntimeError(f'{name}锁定源码不符：{relative}；请按报告获取固定提交')
    dest = Path(root) / 'author' / SOURCE_PINS[name]
    for relative, wanted in expected.items():
        p = dest / relative; p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists() and sha(p) != wanted: raise RuntimeError('作者沙盒被改动，不覆盖：' + str(p))
        if not p.exists(): shutil.copy2(source / relative, p)
    save(Path(root) / 'AUTHOR_PROVENANCE.json', dict(repository=name, commit=SOURCE_PINS[name], file_sha256=expected, redistribution='DIMA由用户直接获取作者公开仓库；本入口不内嵌其源码'))
    return dest


def make_bank(base, root, native):
    trace, bank = base.bank_make(root, native)
    # 已参与旧研究的7401—7404只叫开发回放，不再次冒称未看过的最终测试。
    for item in bank: item['role'] = '开发验证' if item['name'].endswith(('4301', '4302', '4303', '4304')) else '历史已看顺序'
    with Path(trace).open(encoding='utf-8-sig', newline='') as stream:
        reader = csv.DictReader(stream); fields = reader.fieldnames; rows = list(reader)
    spatial = [k for k in fields if k.lower() not in ('id','person_id','time','timestamp','arrival','arrival_time','request_time')]
    for seed in range(8301, 8305):
        od = [{k: r[k] for k in spatial} for r in rows]; random.Random(seed).shuffle(od)
        stream = io.StringIO(newline=''); writer = csv.DictWriter(stream, fieldnames=fields); writer.writeheader()
        writer.writerows([dict(r, **o) for r, o in zip(rows, od)])
        p = root / 'bank' / f'order_{seed}.csv'; blob = stream.getvalue().encode('utf-8')
        if p.exists() and p.read_bytes() != blob: raise RuntimeError('封存顺序变化')
        if not p.exists(): p.write_bytes(blob)
        bank.append(dict(name=p.stem, path=str(p), sha256=sha(p), role='本轮固定设计后的条件重排确认；非新分布'))
    save(root / 'BANK.json', bank)
    return trace, bank


def eval_marks(total, unit=1):
    return sorted({min(total, int(math.ceil(total * fraction / unit) * unit)) for fraction in (.1, .25, .5, .8, .85, .9, .95, 1.)})


def rng_record():
    import numpy as np, torch
    return dict(python=random.getstate(), numpy=np.random.get_state(), torch=torch.get_rng_state(),
                cuda=torch.cuda.get_rng_state_all() if torch.cuda.is_initialized() else None)


def rng_restore(record):
    import numpy as np, torch
    random.setstate(record['python']); np.random.set_state(record['numpy']); torch.set_rng_state(record['torch'])
    if record.get('cuda') is not None: torch.cuda.set_rng_state_all(record['cuda'])


def evaluate(base, m, root, item, bank, predictor_factory, checkpoint, final=False):
    """固定存档，独立策略抽样；冻结归一化，未完成的完整ATT始终为空。"""
    rows = []
    traces = [b for b in bank if b['name'] in ('order_4301','order_4302','order_4303','order_4304') or (final and b['name'].startswith('order_83'))]
    before = rng_record()
    try:
        Phase = base.gym_class(m)
        import numpy as np, torch
        for b in traces:
            seeds = (123, 124, 125) if b['name'].startswith('order_83') else (123, 124)
            for policy_seed in seeds:
                random.seed(policy_seed); np.random.seed(policy_seed); torch.manual_seed(policy_seed)
                predict = predictor_factory(policy_seed)
                env = Phase(root, item, b['path'], 600, 123, False)
                obs, _ = env.reset(seed=123); carry = None
                try:
                    while not env.done:
                        action, carry = predict(obs, carry)
                        obs, _, _, _, _ = env.step(int(action))
                    metrics = env.last_episode
                    logs = metrics['decision_log']; opportunities = [x for x in logs if x['meaningful'] and len(x['legal']) >= 2]
                    vals = sorted(metrics['individual'].values())
                    metrics['p90_cutoff'] = float(np.quantile(vals, .9)); metrics['p95_cutoff'] = float(np.quantile(vals, .95))
                    metrics['multi_target_opportunities'] = len(opportunities)
                    metrics['choice_projection_rate'] = sum(x['requested_target'] != x['applied_target'] for x in opportunities) / max(1, len(opportunities))
                    routing = Counter(x['p'] for x in logs if x.get('passenger_active', True))
                    metrics['actual_passenger_choice_count'] = dict(routing)
                    rows.append(dict(trace=b['name'], trace_sha256=b['sha256'], role=b['role'], policy_seed=policy_seed, environment_seed=123, checkpoint=checkpoint, metrics=metrics))
                finally: env.close()
    finally: rng_restore(before)
    folder = root / 'cells' / item['id']; save(folder / 'eval' / f'{checkpoint:09d}.json', rows)
    return rows


def ready_choice(env,m):
    """沿用11月1日已登记的READY近似规则；不是数学下界，也不升级成新的精确解析器。"""
    if not env.scenario.waiting_decisions: return 0
    s=env.scenario; p=s.persons.persons[s.waiting_decisions[0]]; scores=[]
    for vid in m.CANDIDATES[env.k]:
        v=s.vertiports.vertiport_list[str(vid)]
        access=float(s.vehicles.estimate_travel_time(p.origin_position,v.vertiport_position))
        dist=s.vertiports._calculate_distance(v.vertiport_position,s.vertiports.vertiport_list['2'].vertiport_position)
        flight=dist/200.*60.
        supply=[max(0.,e.spec.battery_capacity_kwh-e.battery_kwh)/max(e.spec.charge_rate_kwh_per_min,1e-9)
            for e in s.vertiports.evtols_at_vertiport.get(str(vid),[]) if not e.passenger_ids and e.state.name in ('IDLE','CHARGING')]
        incoming=sum(str(getattr(p2,'origin_vertiport_id',''))==str(vid) and p2.state=='enroute' and p2.sub_state=='to_vertiport'
            and max(0.,float(p2.current_timer or 0))<=access for p2 in s.persons.persons.values())
        cycle=2*flight+2*dist*.55/5.32
        wait=min(supply,default=flight+dist*.55/5.32)+(len(v.person_list)+incoming)//4*cycle/max(1,len(supply))
        scores.append(max(access,wait)+flight)
    return min(range(env.k),key=lambda i:(scores[i],i))


def rules_once(base,m,root,item,bank):
    if (root/'READY_RULE.json').is_file(): return
    rows=[]; Phase=base.gym_class(m)
    for b in bank:
        if not (b['name'].startswith('order_43') or b['name'].startswith('order_83')): continue
        env=Phase(root,item,b['path'],600,123,False)
        try:
            obs,_=env.reset(seed=123)
            while not env.done:
                a=ready_choice(env.env,m) if env.phase==0 else base.lq_target(env.env)
                obs,_,_,_,_=env.step(a)
            rows.append(dict(trace=b['name'],metrics=env.last_episode))
        finally: env.close()
    save(root/'READY_RULE.json',dict(rows=rows,new_training_transitions=0,
         definition='历史READY乘客规则+响应式最长队调机，同当前三候选及既有投影权限；启发式参照，不是最优下界'))


def decision_probe(base,m,root,item,job,predictor_factory):
    """单次联合决策干预：共同前缀、共同抽样种子、后续同一冻结策略；不冒称CED路径分解。"""
    folder=root/'cells'/item['id']; before=rng_record()
    def rollout(forced=None):
        import numpy as np, torch
        random.seed(8123); np.random.seed(8123); torch.manual_seed(8123)
        predict=predictor_factory(8123); env=base.gym_class(m)(root,item,job['trace'],600,123,False)
        obs,_=env.reset(seed=123); carry=None; minute=0; actual=[]; evidence=None
        try:
            while not env.done:
                phase=env.phase; a,carry=predict(obs,carry)
                if minute==90:
                    if phase==0:
                        evidence=dict(time=float(env.env.scenario.time),passenger_active=bool(env.env.scenario.waiting_decisions))
                    actual.append(int(a))
                    if forced is not None: a=forced[phase]
                obs,_,_,_,info=env.step(int(a)); minute+=int(info['physical_increment'])
            metrics=env.last_episode
            return dict(cost=metrics['fixed_cutoff_cost'],individual=metrics['individual'],evidence=evidence,
                        factual_actions=actual,decision=next((x for x in metrics['decision_log'] if abs(x['time']-90)<1e-8),None))
        finally: env.close()
    try:
        factual=rollout()
        if len(factual['factual_actions'])!=2:
            save(folder/'DECISION_PROBE.json',dict(status='NO_FIXED_WINDOW',new_training_transitions=0)); return
        reference=rollout(factual['factual_actions'])
        if abs(reference['cost']-factual['cost'])>1e-8 or reference['individual']!=factual['individual']:
            raise RuntimeError('共同前缀参考复演不相等；不发布反事实收益')
        rows=[]
        for p in range(3):
            for a in range(3):
                branch=rollout((p,a)); differences=[float(branch['individual'][k])-float(v) for k,v in factual['individual'].items()]
                rows.append(dict(passenger=p,aircraft_intent=a,applied=branch['decision'],cost=branch['cost'],delta=branch['cost']-factual['cost'],
                    helped=sum(v<-1e-7 for v in differences),harmed=sum(v>1e-7 for v in differences),person_time_delta=sum(differences)))
        save(folder/'DECISION_PROBE.json',dict(status='COMPLETE',fixed_minute=90,factual=factual,candidates=rows,
            reference_replay_equal=True,new_training_transitions=0,
            boundary='固定原需求和一次决策的总闭环效应；候选有既有物理投影。不是在线方法，不是全局最优，不是ASE/CED责任路径归因；单窗口只用于补充解释'))
    except Exception:
        save(folder/'DECISION_PROBE_FAILED.json',dict(traceback=traceback.format_exc(),new_training_transitions=0))
    finally: rng_restore(before)


def aggregate(root, tasks):
    rows = []; spent = 0
    for item in tasks:
        folder = root / 'cells' / item['id']; end = read(folder / 'END.json', {}); live = read(folder / 'LIVE.json', {})
        steps = max(int(end.get('real_steps', 0)), int(live.get('real_steps', 0)))
        spent += steps
        rows.append(dict(id=item['id'], arm=item['arm'], phase=item['phase'], seed=item['seed'], target=item['steps'], real_steps=steps,
                         status=end.get('status', 'PENDING'), evaluated=(folder / 'EVALUATION.json').is_file(), seconds=end.get('seconds')))
    charges = list((root/'budget_attempts').glob('*.json')) if (root/'budget_attempts').exists() else []
    measured = sum(read(p,{}).get('observed_increment',0) for p in charges)
    upper = sum(read(p,{}).get('unlogged_upper_bound',0) for p in charges)
    result = dict(total=len(tasks), trained=sum(r['status']=='COMPLETE' for r in rows), evaluated=sum(r['evaluated'] for r in rows),
                  failed=sum(r['status']=='ENGINEERING_FAILED' for r in rows), completed_training_transitions=spent,
                  measured_training_work=measured, interrupted_unlogged_upper_bound=upper, budget_charge_upper_bound=measured+upper,
                  planned_actual_budget=sum(t['steps'] for t in tasks), budget_cap=140_000_000 if SUITE=='core' else 25_000_000, rows=rows, time=time.time())
    save(root / 'progress.json', result)
    return result


def pack(root):
    """结果和模型分包；模型包保留最终件及后期固定存档，不捎带全部回放缓存。"""
    out = PROJECT / 'experiment_archives'; out.mkdir(exist_ok=True)
    for kind in ('DATAONLY', 'FINAL_REPLAY_MODELS'):
        p = out / f'{root.name}_{kind}.tar.gz'; tmp = p.with_name(p.name + '.pending')
        with tarfile.open(tmp, 'w:gz') as archive:
            archive.add(__file__, arcname=root.name+'/ENTRYPOINT.py', recursive=False)
            for file in sorted(root.rglob('*')):
                if not file.is_file() or file.is_symlink() or any(x in file.relative_to(root).parts for x in ('author','vendor','_author_source','adapted_author','adapted_dreamer','cache','replay')): continue
                if '.pending' in file.name: continue
                model = file.suffix in ('.pkl','.pt','.zip','.npz','.ckpt')
                if kind == 'DATAONLY' and model: continue
                if kind == 'FINAL_REPLAY_MODELS' and not (model or file.suffix in ('.json','.yaml','.csv')): continue
                archive.add(file, arcname=root.name+'/'+file.relative_to(root).as_posix(), recursive=False)
        os.replace(tmp, p); save(root / f'{kind}_PACKAGE.json', dict(path=str(p), sha256=sha(p), bytes=p.stat().st_size))
        print('[结果包]', p, flush=True)


def summary(root, tasks):
    """按训练模型汇总，不把多个需求回放当成额外训练种子。"""
    grouped = defaultdict(list); individual = []
    for item in tasks:
        folder = root/'cells'/item['id']; end = read(folder/'END.json', {})
        if end.get('status') != 'COMPLETE': continue
        vals = []
        for p in sorted((folder/'eval').glob('*.json')):
            if int(p.stem)<.8*item['steps']: continue
            vals.extend(x['metrics']['fixed_cutoff_cost'] for x in read(p, []) if x['trace'].startswith('order_43'))
        final = read(folder/'EVALUATION.json', {}).get('final', [])
        confirmation = [r['metrics']['fixed_cutoff_cost'] for r in final if r['trace'].startswith('order_83')]
        row = dict(id=item['id'], arm=item['arm'], seed=item['seed'], phase=item['phase'],
                   late_mean=sum(vals)/len(vals) if vals else None, final_confirmation=sum(confirmation)/len(confirmation) if confirmation else None)
        grouped[(item['phase'],item['arm'])].append(row); individual.append(row)
    import statistics
    groups = []
    for (phase, arm), rows in grouped.items():
        values = [r['late_mean'] for r in rows if r['late_mean'] is not None]
        groups.append(dict(phase=phase, arm=arm, independent_training_seeds=len(values), mean=statistics.mean(values) if values else None,
                           sd=statistics.stdev(values) if len(values)>1 else None, seed_values=rows))
    pairs=[]
    if SUITE=='core':
        contrasts=[('CORE',a,'HAPPO_RANDOM') for a in ('MAPPO_MATCHED','HAPPO_FIXED_PF','HAPPO_FIXED_AF','HAPPO_SHARED','PPO_TF')]
        contrasts += [('DREAMER',a,'DV3_FULL') for a in ('DV3_SHORT','DV3_NO_RECON_REP','DV3_NO_TASK_REP')]
    else:
        contrasts=[('CORE',SUITE.upper()+'_'+a,SUITE.upper()+'_FULL') for a in (('NO_AGG','LOCAL_CONTEXT','SHORT_HORIZON') if SUITE=='marie' else ('JOINT','REVERSE_ORDER','LONG_HORIZON'))]
    for phase, left, right in contrasts:
        lhs={r['seed']:r for r in grouped[(phase,left)]}; rhs={r['seed']:r for r in grouped[(phase,right)]}
        differences=[dict(seed=s,delta=lhs[s]['late_mean']-rhs[s]['late_mean']) for s in sorted(lhs.keys()&rhs.keys()) if lhs[s]['late_mean'] is not None and rhs[s]['late_mean'] is not None]
        values=[r['delta'] for r in differences]; n=len(values)
        # 八个种子报告精确符号翻转；四种子区间明确仅为描述性，不能冒充高功效验证。
        null=[abs(sum(v*(1 if bits&(1<<i) else -1) for i,v in enumerate(values))/n) for bits in range(1<<n)] if n else []
        p=sum(v>=abs(statistics.mean(values))-1e-12 for v in null)/len(null) if null else None
        ci=None
        if n>1:
            tcrit={1:12.706205,2:4.302653,3:3.182446,4:2.776445,5:2.570582,6:2.446912,7:2.364624}[n-1]
            radius=tcrit*statistics.stdev(values)/math.sqrt(n); mu=statistics.mean(values); ci=[mu-radius,mu+radius]
        pairs.append(dict(phase=phase,left=left,right=right,n=n,seed_differences=differences,
             mean_delta=statistics.mean(values) if n else None,descriptive_t_interval_95=ci,exact_sign_flip_p=p,
             direction='正值=左侧成本更差；消融变差支持必要性，但不单独证明交通机制或创新性'))
    save(root/'MODEL_LEVEL_SUMMARY.json', dict(groups=groups, models=individual,paired_contrasts=pairs,
         boundary='每个模型先汇总，再按训练种子配对；主次对照预先指定；多重比较不按最小p挑赢家；未完成组不作成功否定'))


def resume_real(folder):
    return int(read(folder/'RESUME.json',{}).get('real_steps',0))


def finish_attempt(root, attempt_path, returncode):
    record=read(attempt_path); folder=root/'cells'/record['id']
    values=[read(folder/name,{}).get('real_steps',0) for name in ('LIVE.json','END.json','RESUME.json')]
    observed=max([record['initial_real']]+[int(v) for v in values])
    clean=returncode==0 and read(folder/'END.json',{}).get('status') in ('COMPLETE','PARTIAL')
    record.update(observed_increment=max(0,observed-record['initial_real']),
        unlogged_upper_bound=0 if clean else record['loss_bound'],closed=True,returncode=returncode,time=time.time())
    save(attempt_path,record)


def main():
    parser = argparse.ArgumentParser(description='UAM '+SUITE+'作者保真迁移与核心消融')
    parser.add_argument('--plan', action='store_true'); parser.add_argument('--resume', action='store_true')
    parser.add_argument('--retry-failed', action='store_true'); parser.add_argument('--pack-only', action='store_true')
