    if args.pack_only: summary(root,plan['tasks']); pack(root); return
    if shutil.disk_usage(root).free < args.min_free_gib*1024**3: raise RuntimeError('磁盘不足；不删除旧模型')
    base = base_module(); m,native = base.runtime(root, plan['tasks'][0]); trace, bank = make_bank(base,root,native)
    rules_once(base,m,root,plan['tasks'][0],bank)
