        if progress['budget_charge_upper_bound']+future+loss_bound>plan['budget_cap']:
            save(root/'BUDGET_STOP.json',dict(progress=progress,future=future,next_loss_bound=loss_bound,time=time.time()))
            print('[预算保护] 恢复余量不足，保留现状；不自动追加步数',flush=True); break
        attempt_path=root/'budget_attempts'/f'{time.time_ns()}_{item["id"]}.json'
        save(attempt_path,dict(id=item['id'],pid=None,initial_real=initial,loss_bound=loss_bound,closed=False,observed_increment=0,unlogged_upper_bound=loss_bound))
        print(f'[正式任务 {item["run_order"]}/{len(plan["tasks"])}]',item['id'],item['steps'],flush=True)
        with (folder/'worker.log').open('a',encoding='utf-8') as log:
            try:
                proc=subprocess.Popen([python,'-B','-u',__file__,'--worker',str(folder/'JOB.json')],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
            except OSError:
                save(folder/'END.json',dict(status='ENGINEERING_FAILED',real_steps=initial,traceback=traceback.format_exc()))
                finish_attempt(root,attempt_path,0)
