def wm_ablation(learner, item):
    import torch
    if SUITE=='marie' and item['arm'].endswith('NO_AGG'):
        class NoAggregation(torch.nn.Module):
            """去掉跨主体聚合，只保留与输入无关的可学习占位；明确记录参数量变化。"""
            def __init__(self,dimension):
                super().__init__(); self.token=torch.nn.Embedding(2,dimension,device='cuda')
                torch.nn.init.zeros_(self.token.weight)
            def forward(self,data,mask=None,return_cross_attn=False):
                if return_cross_attn: raise RuntimeError('无聚合组没有注意力归因图')
                return self.token.weight[None].expand(data.shape[0],-1,-1)
        learner.model.perattn=NoAggregation(learner.config.TRANS_EMBED_DIM)
        # 原优化器在模型构造后建立，换模块后必须重建，不能让占位参数漏训。
        from utils import configure_optimizer
        learner.model_optimizer=configure_optimizer(learner.model,learner.config.wm_lr,learner.config.wm_weight_decay)
    if SUITE=='marie' and item['arm'].endswith('LOCAL_CONTEXT'):
        module=learner.model.perattn
        class LocalContext(torch.nn.Module):
            """同参数聚合器逐主体仅看本主体token；明确是论文去跨主体聚合的等参数迁移对照。"""
            def __init__(self,inner): super().__init__(); self.inner=inner
            def forward(self,data,mask=None,return_cross_attn=False):
                if return_cross_attn: raise RuntimeError('局部对照不伪造跨主体注意力图')
                if data.shape[1]%2: raise RuntimeError('token主体分组不一致')
                width=data.shape[1]//2
                return torch.stack([self.inner(data[:,i*width:(i+1)*width],mask=None)[:,i] for i in range(2)],dim=1)
        learner.model.perattn=LocalContext(module)
    if SUITE=='dima' and item['arm'].endswith('JOINT'):
        original=type(learner.denoiser).compute_model_output
        def joint(self,noisy_next_obs,obs,act,cs,act_mask):
            # 训练和采样均在每次去噪看完整联合动作；去噪次数、网络参数与优化器不变。
            return original(self,noisy_next_obs,obs,act,cs,torch.ones_like(act_mask))
        learner.denoiser.compute_model_output=types.MethodType(joint,learner.denoiser)


def role_observations(vector):
    import numpy as np
    x=np.asarray(vector,np.float32)
    return np.stack([np.concatenate([x,np.eye(2,dtype=np.float32)[i]]) for i in range(2)])


def role_availability(vector):
    import numpy as np
    phase=int(round(float(vector[-8]))); mask=np.zeros((2,3),np.float32)
    mask[:,0]=1.; mask[phase]=1.
    return mask


def wm_train(job):
    import numpy as np, torch, cloudpickle
    root=Path(job['root']); item=job['task']; folder=root/'cells'/item['id']; started=time.time()
    base=base_module(); m,_=base.runtime(root,item); Phase=base.gym_class(m)
    author=wm_source(root,job['vendor_dir']); sys.path.insert(0,str(author))
    # 作者通用模块名可能与项目重名；训练前不曾导入另一篇的模型。
    for name in ('agent','configs','networks','dataset','episode','environments','utils'):
        present=sys.modules.get(name)
        if present and getattr(present,'__file__',None) and not Path(present.__file__).resolve().is_relative_to(author.resolve()):
            raise RuntimeError('作者模块名被占用：'+name)
    import wandb
    wandb.init(project='uam_'+SUITE,mode='disabled',dir=str(folder))
    torch.manual_seed(item['seed']); np.random.seed(item['seed']); random.seed(item['seed'])
    env=Phase(root,item,job['trace'],500,item['seed'],False); obs,_=env.reset(seed=item['seed'])
    learner_config,controller_config=wm_configs(folder,item,len(obs)+2,len(obs))
    from agent.controllers.DreamerController import DreamerController
    pointer=read(folder/'RESUME.json',{})
    if pointer:
        resume=folder/'replay'/pointer['full_file']
        if not resume.is_file() or sha(resume)!=pointer['full_sha256']: raise RuntimeError('完整模型/优化器/回放恢复件不符，不从头偷偷重训')
        with resume.open('rb') as stream: payload=cloudpickle.load(stream)
        learner=payload['learner']; real=payload['real_steps']; records=payload['decision_records']; rng_restore(payload['rng'])
    else:
        learner=learner_config.create_learner(); wm_ablation(learner,item); real=0; records=0
    initial=real; controller=DreamerController(controller_config)
    last_save=time.time(); updates=int(learner.train_count); pending=[]
    def actor_factory(seed):
        frozen=copy.deepcopy(learner.params())
        def factory(policy_seed):
            c=DreamerController(controller_config); c.receive_params(frozen)
            def predict(x,carry):
                observations=torch.from_numpy(role_observations(x))[None]
                available=torch.from_numpy(role_availability(x))[None]
                if SUITE=='marie': action,_=c.step(observations,available,None)
                else: action,_=c.step(observations,torch.from_numpy(np.asarray(x,np.float32))[None,None].repeat(1,2,1),available,None)
                phase=int(round(float(x[-8])))
                return int(action[phase].argmax().item()),None
            return predict
        return factory
    def checkpoint(full=True):
        nonlocal last_save
        if full:
            resume=folder/'replay'/f'RESUME_FULL_{real:09d}.pkl'
            resume.parent.mkdir(parents=True,exist_ok=True)
            previous=read(folder/'RESUME.json',{})
            temporary=resume.with_name(resume.name+'.pending')
            with temporary.open('wb') as stream: cloudpickle.dump(dict(learner=learner,real_steps=real,decision_records=records,rng=rng_record()),stream,protocol=5)
            os.replace(temporary,resume)
            save(folder/'RESUME.json',dict(real_steps=real,decision_records=records,full_file=resume.name,full_sha256=sha(resume),boundary='完整优化器和回放恢复；新episode重新开始，非位级仿真续接'))
            if previous.get('full_file') and previous['full_file']!=resume.name:
                stale=resume.parent/previous['full_file']
                if stale.is_file() and stale.parent.resolve()==resume.parent.resolve(): stale.unlink()
        weights=folder/'FINAL.pt'; temporary=weights.with_name('FINAL.pending.pt')
        torch.save(learner.params(),temporary); os.replace(temporary,weights); last_save=time.time()
    def flush():
        nonlocal pending,updates
        if not pending: return
        rollout={key:np.asarray([row[key] for row in pending],np.float32) for key in pending[0]}
        rollout['last']=np.zeros_like(rollout['done']); rollout['last'][-1]=1.
        learner.mamba_replay_buffer._uam_terminal=rollout['terminal']
        learner.step(rollout); updates=int(learner.train_count); pending=[]
        controller.receive_params(learner.params())
    try:
        controller.receive_params(learner.params())
        while real<job['steps'] and not stopping(root):
            x=obs.copy(); observed=role_observations(x); available=role_availability(x)
            observations=torch.from_numpy(observed)[None]; av=torch.from_numpy(available)[None]
            if SUITE=='marie': action,entropy=controller.step(observations,av,None)
            else: action,entropy=controller.step(observations,torch.from_numpy(x)[None,None].repeat(1,2,1),av,None)
            phase=int(round(float(x[-8]))); chosen=int(action[phase].argmax().item())
            obs,reward,_,done,info=env.step(chosen); real+=int(info['physical_increment']); records+=1
            terminal=bool(done and env.last_episode['unfinished']==0)
            row=dict(observation=observed,action=action.detach().cpu().numpy(),reward=np.full((2,1),reward,np.float32),
                done=np.full((2,1),done,np.float32),terminal=np.full((2,1),terminal,np.float32),fake=np.zeros((2,1),np.float32),
                avail_action=available,entropy=entropy.detach().cpu().numpy())
            if SUITE=='dima':
                row['shared_obs']=np.repeat(x[None],2,axis=0); row['next_shared_obs']=np.repeat(obs[None],2,axis=0)
            pending.append(row)
            if records%100==0:
                save(folder/'LIVE.json',dict(real_steps=real,decision_records=records,model_training_rounds=updates,
                    seconds=time.time()-started,real_fps=(real-initial)/max(1,time.time()-started),time=time.time()))
            # 与作者worker一致：收集完整回合后交给原learner，由其N_SAMPLES/MIN_BUFFER_SIZE判断更新。
            # 只有矩阵目标结束时允许最后一段截短，不自行改成每100条就更新的另一种算法。
            if done or real>=job['steps']:
                flush()
                save(folder/'LIVE.json',dict(real_steps=real,decision_records=records,model_training_rounds=updates,
                    seconds=time.time()-started,real_fps=(real-initial)/max(1,time.time()-started),time=time.time()))
                if time.time()-last_save>=600 or real>=job['steps']: checkpoint()
                for mark in job['marks']:
                    if real>=mark and not (folder/'eval'/f'{mark:09d}.json').exists():
                        checkpoint(); torch.save(learner.params(),folder/f'CP_{mark:09d}.pt')
                        final=evaluate(base,m,root,item,job['bank'],actor_factory(123),mark,final=real>=job['steps'])
            if done:
                obs,_=env.reset(); controller.init_rnns()
        flush(); checkpoint()
        complete=real>=job['steps']
        if complete:
            final=read(folder/'eval'/f'{job["marks"][-1]:09d}.json',[])
            save(folder/'EVALUATION.json',dict(final=final,real_steps=real,decision_records=records,weights_unchanged=True))
            prediction_probe(base,m,root,item,learner,job)
            decision_probe(base,m,root,item,job,actor_factory(123))
        save(folder/'END.json',dict(status='COMPLETE' if complete else 'PARTIAL',real_steps=real,decision_records=records,
             model_training_rounds=updates,seconds=time.time()-started,author_commit=SOURCE_PINS[SUITE]))
        if complete:
            # 本轮已完成格只保留最终与五个固定模型；释放自己创建的巨大恢复缓存，不碰历史实验。
            pointer=read(folder/'RESUME.json',{})
            cache=folder/'replay'/pointer['full_file']
            save(folder/'RESUME.json',dict(real_steps=real,decision_records=records,model='FINAL.pt',model_sha256=sha(folder/'FINAL.pt'),
                completed_cache_released=True,boundary='完整格不再续训；可回放，原回放缓存不再保留'))
            if cache.is_file() and cache.parent.resolve()==(folder/'replay').resolve(): cache.unlink()
    finally: env.close(); wandb.finish()


def prediction_probe(base,m,root,item,learner,job):
    """借鉴固定共同数据检验，不用各自坏策略轨迹的RMSE冒充模型根因。"""
    import numpy as np, torch
    Phase=base.gym_class(m); state_before=rng_record(); result=[]
    try:
        env=Phase(root,item,job['trace'],500,9001,False); x,_=env.reset(seed=9001)
        data=[]
        for record in range(260):
            phase=int(round(float(x[-8]))); obs=role_observations(x)
            chosen=(record//2)%3 if phase==0 else base.lq_target(env.env)
            actions=np.zeros((2,3),np.float32); actions[:,0]=1.; actions[phase]=np.eye(3,dtype=np.float32)[chosen]
            nxt,_,_,done,_=env.step(chosen)
            data.append(dict(state=x.copy(),obs=obs,action=actions,next=nxt.copy())); x=nxt
            if done: break
        env.close()
        signature=hashlib.sha256(b''.join(r['state'].tobytes()+r['action'].tobytes() for r in data)).hexdigest()
        starts=(20,60,100,140,180)
        for start in starts:
            if start+30>=len(data): continue
            if SUITE=='marie':
                from agent.models.world_model_env import MAWorldModelEnv
                from environments import Env
                simulator=MAWorldModelEnv(env=None,world_model=learner.model,tokenizer=learner.tokenizer,device='cuda',env_type=Env.STARCRAFT)
                simulator.reset_from_initial_observations(torch.as_tensor(data[start]['obs'],device='cuda')[None])
                predictions=[]
                for offset in range(30):
                    action=torch.as_tensor(data[start+offset]['action'].argmax(-1),device='cuda')[None,:,None]
                    predicted,*_=simulator.step(action)
                    predictions.append(predicted.detach().cpu().numpy()[0])
                targets=[role_observations(data[start+i]['next']) for i in range(30)]
            else:
                from agent.world_models.diffusion import DiffusionSampler
                sampler=DiffusionSampler(learner.denoiser,learner.config.diffusion_sampler_cfg)
                n=learner.config.denoiser_cfg.inner_model.num_steps_conditioning
                states=torch.as_tensor(np.stack([data[i]['state'] for i in range(start-n+1,start+1)]),device='cuda')[None]
                states=learner.denoiser.encode(learner.normalize_state(states))
                predictions=[]
                for offset in range(30):
                    actions=torch.as_tensor(np.stack([data[i]['action'] for i in range(start+offset-n+1,start+offset+1)]),device='cuda')[None]
                    next_state,_=sampler.sample(states,actions)
                    decoded=learner.denoiser.decode(next_state)
                    decoded=decoded*torch.sqrt(torch.as_tensor(learner.state_rms.var+1e-8,device='cuda'))+torch.as_tensor(learner.state_rms.mean,device='cuda')
                    predictions.append(decoded.detach().cpu().numpy().reshape(-1))
                    states=torch.cat([states[:,1:],next_state.reshape(1,1,-1)],dim=1)
                targets=[data[start+i]['next'] for i in range(30)]
            for minute in (1,5,15):
                error=np.asarray(predictions[2*minute-1])-np.asarray(targets[2*minute-1])
                result.append(dict(start_record=start,physical_minutes=minute,raw_vector_rmse=float(np.sqrt(np.mean(error**2)))))
        save(root/'cells'/item['id']/'COMMON_STATE_MODEL_FIT.json',dict(data_sha256=signature,rows=result,new_training_transitions=0,
             boundary='相同合法规则轨迹与实际动作；不是不同策略自身分布误差；不同量纲另行分析；不声称RMSE证明候选排序正确'))
    except Exception:
        # 诊断器失败必须独立呈现，不能抹掉已完成训练或伪造零误差。
        save(root/'cells'/item['id']/'DIAGNOSTIC_FAILED.json',dict(traceback=traceback.format_exc(),new_training_transitions=0))
    finally: rng_restore(state_before)


if __name__ == "__main__":
    main()
